import{_ as t,a,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · Lesson 22 A glass envelope","description":"学习 动词、宾语与补足语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 22 A glass envelope","description":"学习 动词、宾语与补足语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 动词、宾语与补足语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 21 Mad or not?","link":"/life/english/new-concept/book-2/unit-01/lesson-021"},"next":{"text":"第二册：实践与进步 · Lesson 23 A new house","link":"/life/english/new-concept/book-2/unit-01/lesson-023"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 21 Mad or not?","link":"/life/english/new-concept/book-2/unit-01/lesson-021"},"next":{"text":"第二册：实践与进步 · Lesson 23 A new house","link":"/life/english/new-concept/book-2/unit-01/lesson-023"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-022.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-022.md"}'),n={name:"life/english/new-concept/book-2/unit-01/lesson-022.md"};function l(i,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第二册-实践与进步-·-lesson-22-a-glass-envelope" tabindex="-1">第二册：实践与进步 · Lesson 22 A glass envelope <a class="header-anchor" href="#第二册-实践与进步-·-lesson-22-a-glass-envelope" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 22 A glass envelope&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>漂流物中的留言多年后被陌生人读到，形成跨越距离的联系；练习带介词的动词搭配。本课的语言观察是：reply to 与 answer 的结构不同：reply to a message 必须保留 to，answer a message 可以直接接宾语。不要因中文都有“回复”就套同一结构。完成学习后，请写一段意外收到旧消息的经历，交代发现、回复和反应。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>bottle</td><td>/ˈbɒtəl/</td><td>n.</td><td>瓶子</td><td>a glass bottle</td></tr><tr><td>coast</td><td>/kəʊst/</td><td>n.</td><td>海岸</td><td>along the coast</td></tr><tr><td>reply</td><td>/rɪˈplaɪ/</td><td>v.</td><td>回复</td><td>reply promptly</td></tr><tr><td>discover</td><td>/dɪˈskʌvə/</td><td>v.</td><td>发现</td><td>discover a note</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>reply to a message — 回复一条消息</li><li>hear from somebody — 收到某人的来信或消息</li></ul><h2 id="语法讲解-动词、宾语与补足语" tabindex="-1">语法讲解：动词、宾语与补足语 <a class="header-anchor" href="#语法讲解-动词、宾语与补足语" aria-label="Permalink to &quot;语法讲解：动词、宾语与补足语&quot;">​</a></h2><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：reply to 与 answer 的结构不同：reply to a message 必须保留 to，answer a message 可以直接接宾语。不要因中文都有“回复”就套同一结构。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>A walker replied to the message inside the bottle.</p></blockquote><p>一位徒步者回复了瓶子里的留言。</p><p>replied 是谓语，to the message 是必要的介词补足部分；inside the bottle 修饰 message 的所在位置。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>reply the message 通常应改为 reply to the message；answer the message 则不加 to。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>连读 replied to，注意 replied 的 /d/；把 inside the bottle 连成一个地点语块。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A walker replied to the message inside the bottle. He found it during a walk along the coast. The writer had almost forgotten sending it.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段意外收到旧消息的经历，交代发现、回复和反应。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：replied 是谓语，to the message 是必要的介词补足部分；inside the bottle 修饰 message 的所在位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：reply the message 通常应改为 reply to the message；answer the message 则不加 to。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填介词：She replied ___ my message.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> reply 搭配 to 引出回复对象。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>作者是否还一直记得那次寄信？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. The writer had almost forgotten it.</p><p><strong>解析：</strong> almost forgotten 表几乎忘记，不表示完全忘得一干二净。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 answer 改写 She replied to the message。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She answered the message.</p><p><strong>解析：</strong> answer 作动词可直接接宾语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动词、宾语与补足语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-021">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-023">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=t(n,[["render",l]]);export{g as __pageData,u as default};
